// Only references generated by the web-film checkout routes are eligible.
const paystackFilm = /^WEB_(?:[1-9]\d*_[1-9]\d*_\d{13}_[a-f0-9]{8}|APP_[a-f0-9]{32})$/;
const flutterwaveFilm = /^FLW_FILM_(?:APP_)?[a-f0-9]{32}$/;

export function registerFilmPaymentRecheck({
  app, prisma, requireAdmin, verifyPaystack, verifyFlutterwave, fulfill,
}) {
  app.post("/api/admin/transactions/recheck-film-payment", requireAdmin, async (req, res) => {
    res.set("Cache-Control", "no-store");
    const reference = typeof req.body?.reference === "string" ? req.body.reference : "";
    const verify = reference.length <= 100 && (paystackFilm.test(reference)
      ? verifyPaystack : flutterwaveFilm.test(reference) ? verifyFlutterwave : null);
    if (!verify) return res.status(400).json({ success: false, message: "Wannan reference ba na sayen fim ta Paystack ko Flutterwave ba ne." });

    try {
      const order = await prisma.webOrder.findUnique({ where: { paymentReference: reference } });
      if (!order) return res.status(404).json({ success: false, message: "Ba a samu odar fim ba." });
      if (order.status === "paid") return res.json({ success: true, status: "paid", message: "An riga an tabbatar da wannan odar." });
      if (order.status !== "pending") {
        return res.status(409).json({ success: false, message: "Wannan odar ba ta Pending." });
      }

      const payment = await verify(reference);
      if (!payment) {
        return res.status(502).json({ success: false, message: "Ba a samu tabbaci daga kamfanin biyan kuɗi ba. Duba odar a dashboard ɗinsa." });
      }
      if (payment.reference !== reference) {
        return res.status(409).json({ success: false, message: "Reference ɗin biyan kuɗi bai dace da odar ba." });
      }
      if (!payment.paid) {
        return res.json({ success: true, status: "unconfirmed", message: "Kamfanin biyan kuɗi bai tabbatar da nasara ba. Ba a buɗe fim ba." });
      }
      if (payment.currency !== "NGN" || !Number.isSafeInteger(payment.amountKobo) ||
          payment.amountKobo <= 0 || payment.amountKobo !== order.amount * 100) {
        return res.status(409).json({ success: false, message: "Adadi ko currency bai dace da odar ba. Ba a buɗe fim ba." });
      }

      const result = await fulfill({ reference, paidAmount: payment.amountKobo });
      if (!result?.success) {
        return res.status(503).json({ success: false, message: "An tabbatar an biya, amma ba a samu damar buɗe fim ba. Sake dubawa daga baya." });
      }
      return res.json({ success: true, status: "paid", message: "An tabbatar an biya. Mai saya zai ga fim ɗin a My Movies." });
    } catch (error) {
      console.error("FILM PAYMENT RECHECK FAILED:", error.code || error.name);
      return res.status(503).json({ success: false, message: "An kasa sake duba wannan odar. Sake gwadawa daga baya." });
    }
  });
}
